import{r as n,j as e}from"./chunk-CuooTuTj.js";/* empty css              */const i=[{id:"platform",label:"Platform",questions:[{q:"What is the Governance Resource Hub (GRH)?",a:"The GRH is a digital platform that centralises state-level fiscal data, governance research, and professional learning resources for policy makers, researchers, and civil society organisations across Nigeria."},{q:"Is the platform free to use?",a:"Yes. All public data, research resources, and learning courses are free and open-access. Certain premium features such as certificate downloads and personalised dashboards require a free account."},{q:"How do I create an account?",a:'Click "Sign Up" at the top of the page, enter your email address, and follow the verification steps. You can also use a Magic Link — no password required.'},{q:"What devices and browsers are supported?",a:"The GRH is fully responsive and works on any modern browser (Chrome, Firefox, Safari, Edge) on desktops, tablets, and mobile phones."},{q:"How often is the platform updated with new content?",a:"Data is updated quarterly in line with official government reporting cycles. Research resources and courses are added on a rolling basis as new materials are verified and published."}]},{id:"data",label:"Data & Analytics",questions:[{q:"Where does the fiscal data come from?",a:"All fiscal data is compiled from official sources including the National Bureau of Statistics (NBS), the Central Bank of Nigeria (CBN), and individual state government budget documents."},{q:"How accurate is the data on the platform?",a:"We strive for 99.9% data accuracy. All figures are cross-referenced against primary sources. However, government data is subject to revision, and we clearly flag any data that has been updated retrospectively."},{q:"Can I download or export data?",a:"Yes. Most datasets are available for download in CSV and PDF formats. Click the Download icon on any data table or chart to export the data for your own analysis."},{q:"How do I compare data across multiple states?",a:"Use the Open Comparator tool on the Analyse page. Select up to five states from the dropdown and choose the metrics you want to compare. The tool generates side-by-side visualisations instantly."},{q:"Who can I contact if I spot an error in the data?",a:"Please use the Feedback button at the bottom of any data page or email us at data@grh.ng. We review all submissions within 48 hours and issue corrections with a transparent changelog."}]},{id:"learning",label:"Learning",questions:[{q:"How do the learning courses work?",a:"Courses are self-paced and structured into modules with video lectures, reading materials, and short assessments. You can start, pause, and resume any course at any time from any device."},{q:"Do I receive a certificate upon completion?",a:"Yes. Completing all modules and passing the final assessment earns you a verified digital certificate. Certificates can be downloaded as PDFs and shared on LinkedIn or other platforms."},{q:"Are the courses accredited?",a:"Courses are developed in partnership with leading governance institutions, including PEFA Secretariat, IDEA International, and UNDP. Accreditation status is shown on each course page."},{q:"Can organisations enrol their teams?",a:"Yes. We offer team enrolments and institutional partnerships that include bulk access, progress tracking for managers, and customised learning paths. Contact us at partnerships@grh.ng."},{q:"What happens if I fail a course assessment?",a:"You can retake any assessment up to three times. After three attempts, you must wait 48 hours before trying again. Your highest score is always recorded on your profile."}]},{id:"research",label:"Research Library",questions:[{q:"What types of resources are in the library?",a:"The library contains policy papers, technical handbooks, research reports, and case studies across governance themes including PFM, anti-corruption, electoral systems, and digital governance."},{q:"How do I find resources relevant to my topic?",a:"Use the search bar to search by title, keyword, or author. You can also apply filters by Programme (SLGP, SPARC, PERL), Location (state), or Thematic Area to narrow results."},{q:"Can I upload or contribute a resource?",a:"Resource submissions are welcome. Submit your document via the Contribute button on the Library page. All submissions are reviewed by our editorial team before publication."},{q:"Are all resources available in PDF?",a:"Most resources include a PDF download. For resources hosted externally, we provide a verified link to the publisher. If a PDF is unavailable, the resource will display an executive summary."},{q:"How are resources categorised?",a:"Resources are tagged by Programme (SLGP, SPARC, PERL, BOOK), Thematic Area, and Geographic Location. Each resource card shows these tags to help you quickly assess relevance."}]}],p=()=>{const[t,c]=n.useState("platform"),[r,o]=n.useState(null),l=i.find(a=>a.id===t),d=a=>o(r===a?null:a);return e.jsxs("section",{className:"faq-section",children:[e.jsxs("div",{className:"faq-hero",children:[e.jsx("div",{className:"faq-hero-overlay"}),e.jsxs("div",{className:"faq-hero-content",children:[e.jsx("h2",{children:"How can we help you?"}),e.jsx("p",{children:"Find answers to frequently asked questions about our platform, data, and courses."})]})]}),e.jsx("div",{className:"faq-tabs-bar",children:i.map(a=>e.jsx("button",{className:`faq-tab-btn ${t===a.id?"active":""}`,onClick:()=>{c(a.id),o(null)},children:a.label},a.id))}),e.jsx("div",{className:"faq-body container",children:e.jsx("div",{className:"faq-accordion",children:l.questions.map((a,s)=>e.jsxs("div",{className:`faq-item ${r===s?"open":""}`,children:[e.jsxs("button",{className:"faq-question",onClick:()=>d(s),children:[e.jsx("span",{children:a.q}),e.jsx("span",{className:"faq-icon",children:e.jsx("span",{className:"material-symbols-outlined",children:r===s?"keyboard_arrow_up":"keyboard_arrow_down"})})]}),e.jsx("div",{className:"faq-answer",children:e.jsx("p",{children:a.a})})]},s))})})]})};export{p as F};
